F('st13 분량 보충','오늘의 베이즈 방법을 상당 부분 앞질렀다고 평가했다.','오늘의 베이즈 방법을 상당 부분 앞질렀다고 평가했다. 같은 호에 실린 토론에서 겔먼(2009)은 제프리스의 사전 규칙을 오늘의 계층 모형의 눈으로 다시 읽으며, 규칙 사전이 모형의 다른 부분과 따로 정해질 수 없다는 점을 짚었다.')

def run():
    src={f:open(f,encoding='utf-8').read() for f in FILES}
    ok=0; bad=[]; already=0
    for tag,o,n in FIX:
        hits=[(f,s.count(o)) for f,s in src.items() if o in s]
        tot=sum(c for _,c in hits)
        if tot==0 and (n=='' or any(n in v for v in src.values())): already+=1; continue
        if tot!=1: bad.append((tag,tot)); continue
        f=hits[0][0]; src[f]=src[f].replace(o,n); ok+=1
    for f,s in src.items(): open(f,'w',encoding='utf-8').write(s)
    print('applied',ok,'already',already,'skipped',len(bad))
    for b in bad: print('  SKIP',b)
if __name__=='__main__': run()
